+fn apply_lays_the_stock_along_x_and_undo_stands_it_up_again() {
+    let mut h = stock_page_with_cylinder();
+    assert!(same_turn(stock_rot(&h), [0.0, 0.0, 0.0, 1.0]));
+    h.get_by_label("Along X").click();
